/** A launch the settings contract refuses: the Solidity error and its arguments. */
export class BankrV4ResolveRevert extends Error {
  constructor(
    readonly error: string,
    readonly args: readonly (bigint | number | Address | Hex)[] = [],
  ) {
    super(`resolve reverts ${error}(${args.join(", ")})`);
    this.name = "BankrV4ResolveRevert";
  }
}

export const revert = (
  error: string,
  ...args: BankrV4ResolveRevert["args"]
): never => {
  throw new BankrV4ResolveRevert(error, args);
};
export const hold = (v: BankrV4BoundVerdict): void => {
  if (v) revert(v.error, ...v.args);
};

