/**
 * SettingsRead.range: a pad's knob as a launch meets it. The overlap of the pad's row and the owner's limit, or the
 * nearest edge of the limit where the owner has since moved it past the row, with the default clamped inside.
 */
export function bankrV4KnobInForce(
  s: {
    pad: Pick<BankrV4PadConfig, "ranges">;
    limits: readonly BankrV4Limit[];
  },
  knob: BankrV4KnobName,
): BankrV4Range {
  const r = { ...s.pad.ranges[K[knob]]! };
  const l = s.limits[K[knob]]!;
  if (r.min < l.min) r.min = l.min;
  if (r.min > l.max) r.min = l.max;
  if (r.max > l.max) r.max = l.max;
  if (r.max < l.min) r.max = l.min;
  if (r.dflt < r.min) r.dflt = r.min;
  if (r.dflt > r.max) r.dflt = r.max;
  return r;
}

const KNOB_NAMES = Object.keys(K) as BankrV4KnobName[];
export const range = (x: Ctx, knob: number): BankrV4Range =>
  bankrV4KnobInForce({ pad: x.pad, limits: x.s.limits }, KNOB_NAMES[knob]!);

export function pick(
  x: Ctx,
  knob: number,
  bit: number,
  v: bigint | number,
): bigint {
  const r = range(x, knob);
  if ((x.set & bit) === 0) return r.dflt;
  const value = BigInt(v);
  if (value < r.min || value > r.max) {
    revert("OutsideLaunchpadRange", knob, r.min, r.max);
  }
  return value;
}

export function under(x: Ctx, knob: number, v: bigint | number): bigint {
  const r = range(x, knob);
  if (BigInt(v) > r.max) revert("OutsideLaunchpadRange", knob, r.min, r.max);
  return r.max;
}

export const flag = (x: Ctx, f: bigint): void => {
  if ((x.flags & f) === 0n) revert("NotAllowedByLaunchpad", f);
};
export const unset = (x: Ctx, bits: number): void => {
  if ((x.set & bits) !== 0) revert("InvalidOptions");
};

